def f(n, points):
    MINI = -10000
    MAXI =  10000
    big_S = -float('_inf')
    x_left =  MAXI
    y_low = MAXI
    x_right = -float('inf')
    y_up = -float('inf')
    for value in points:
        x, y = value
        if x - x_left <= 1:
            if y - y_low <= 1:
                big_S = max(big_S, 1)
        if x - x_right <= 1:
            if y - y_up <= 1:
                big_S = max(big_S, 1)
        if 2 <= x: 
            x_left = max(x_left, x-2)
            if y - y_low <= 1:
                big_S = max(big_S, 1)
        if 2 <= y:
            y_low = max(y_low, y-2)
            if x - x_left <= 1:
                big_S = max(big_S, 1)
    return big_S * 2 +  7 - (n*(largest notach mesured in that edge))

